sealed class CodexServerRequest implements CodexJsonEncodable {
  const CodexServerRequest();
  factory CodexServerRequest.fromJson(Object? json) {
    final map = CodexJson.asMap(json, 'CodexServerRequest');
    switch (map['method']) {
      case 'item/commandExecution/requestApproval':
        return CodexItemCommandExecutionRequestApprovalRequest.fromJson(map);
      case 'item/fileChange/requestApproval':
        return CodexItemFileChangeRequestApprovalRequest.fromJson(map);
      case 'item/tool/requestUserInput':
        return CodexItemToolRequestUserInputRequest.fromJson(map);
      case 'mcpServer/elicitation/request':
        return CodexMcpServerElicitationRequestRequest.fromJson(map);
      case 'item/permissions/requestApproval':
        return CodexItemPermissionsRequestApprovalRequest.fromJson(map);
      case 'item/tool/call':
        return CodexItemToolCallRequest.fromJson(map);
      case 'account/chatgptAuthTokens/refresh':
        return CodexAccountChatgptAuthTokensRefreshRequest.fromJson(map);
      case 'attestation/generate':
        return CodexAttestationGenerateRequest.fromJson(map);
      case 'currentTime/read':
        return CodexCurrentTimeReadRequest.fromJson(map);
      case 'applyPatchApproval':
        return CodexApplyPatchApprovalRequest.fromJson(map);
      case 'execCommandApproval':
        return CodexExecCommandApprovalRequest.fromJson(map);
      default:
        return CodexUnknownMessage(map);
    }
  }
}

