sealed class CodexConfigLayerSource implements CodexJsonEncodable {
  const CodexConfigLayerSource();
  factory CodexConfigLayerSource.fromJson(Object? json) {
    final map = CodexJson.asMap(json, 'CodexConfigLayerSource');
    switch (map['type']) {
      case 'mdm':
        return CodexMdmConfigLayerSource.fromJson(map);
      case 'system':
        return CodexSystemConfigLayerSource.fromJson(map);
      case 'enterpriseManaged':
        return CodexEnterpriseManagedConfigLayerSource.fromJson(map);
      case 'user':
        return CodexUserConfigLayerSource.fromJson(map);
      case 'project':
        return CodexProjectConfigLayerSource.fromJson(map);
      case 'sessionFlags':
        return CodexSessionFlagsConfigLayerSource.fromJson(map);
      case 'legacyManagedConfigTomlFromFile':
        return CodexLegacyManagedConfigTomlFromFileConfigLayerSource.fromJson(
          map,
        );
      case 'legacyManagedConfigTomlFromMdm':
        return CodexLegacyManagedConfigTomlFromMdmConfigLayerSource.fromJson(
          map,
        );
      default:
        return CodexConfigLayerSourceUnknown(map);
    }
  }
}

