sealed class CodexThreadItem implements CodexJsonEncodable {
  const CodexThreadItem();
  factory CodexThreadItem.fromJson(Object? json) {
    final map = CodexJson.asMap(json, 'CodexThreadItem');
    switch (map['type']) {
      case 'userMessage':
        return CodexUserMessageThreadItem.fromJson(map);
      case 'hookPrompt':
        return CodexHookPromptThreadItem.fromJson(map);
      case 'agentMessage':
        return CodexAgentMessageThreadItem.fromJson(map);
      case 'plan':
        return CodexPlanThreadItem.fromJson(map);
      case 'reasoning':
        return CodexReasoningThreadItem.fromJson(map);
      case 'commandExecution':
        return CodexCommandExecutionThreadItem.fromJson(map);
      case 'fileChange':
        return CodexFileChangeThreadItem.fromJson(map);
      case 'mcpToolCall':
        return CodexMcpToolCallThreadItem.fromJson(map);
      case 'dynamicToolCall':
        return CodexDynamicToolCallThreadItem.fromJson(map);
      case 'collabAgentToolCall':
        return CodexCollabAgentToolCallThreadItem.fromJson(map);
      case 'subAgentActivity':
        return CodexSubAgentActivityThreadItem.fromJson(map);
      case 'webSearch':
        return CodexWebSearchThreadItem.fromJson(map);
      case 'imageView':
        return CodexImageViewThreadItem.fromJson(map);
      case 'sleep':
        return CodexSleepThreadItem.fromJson(map);
      case 'imageGeneration':
        return CodexImageGenerationThreadItem.fromJson(map);
      case 'enteredReviewMode':
        return CodexEnteredReviewModeThreadItem.fromJson(map);
      case 'exitedReviewMode':
        return CodexExitedReviewModeThreadItem.fromJson(map);
      case 'contextCompaction':
        return CodexContextCompactionThreadItem.fromJson(map);
      default:
        return CodexThreadItemUnknown(map);
    }
  }
}

